input.content:
:root {
  --ink: #171335;
  --muted: #6d6887;
  --muted-soft: #8a85a3;
  --bg: #f8f7ff;
  --card: #ffffff;
  --line: #e9e6f7;
  --indigo: #5b4bff;
  --violet: #8b5cf6;
  --pink: #ff4d8d;
  --teal: #0fbea6;
  --sky: #2aa8ff;
  --green: #12b886;
  --danger: #d92d20;
  --shadow: 0 24px 60px -40px rgba(40, 20, 100, 0.4);
  --radius: 22px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  font-family: "Inter", "Segoe UI", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;
  color: var(--ink);
  background:
    radial-gradient(900px 520px at 6% -6%, #ece7ff 0%, transparent 60%),
    radial-gradient(820px 480px at 102% 3%, #ffe8f2 0%, transparent 58%),
    var(--bg);
  background-attachment: fixed;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body.modal-open {
  overflow: hidden;
}

h1,
h2,
h3,
h4 {
  margin: 0;
  line-height: 1.12;
  letter-spacing: -0.02em;
}

p {
  margin: 0;
}

ul,
ol {
  margin: 0;
  padding: 0;
  list-style: none;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font: inherit;
}

input,
select,
textarea {
  font: inherit;
  color: inherit;
}

img,
svg {
  max-width: 100%;
}

[hidden] {
  display: none !important;
}

::selection {
  background: #cfc7ff;
  color: #1b1250;
}

:focus-visible {
  outline: 3px solid rgba(91, 75, 255, 0.45);
  outline-offset: 2px;
}

.container {
  width: min(1180px, calc(100% - 48px));
  margin-inline: auto;
}

.icon {
  width: 1em;
  height: 1em;
  flex: none;
  display: inline-block;
  vertical-align: -0.12em;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 60;
  background: rgba(255, 255, 255, 0.84);
  border-bottom: 1px solid rgba(233, 230, 247, 0.9);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
}

.nav-shell {
  width: min(1180px, calc(100% - 48px));
  margin-inline: auto;
  height: 74px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  font-weight: 800;
  font-size: 1.16rem;
  letter-spacing: -0.03em;
}

.brand-mark {
  width: 40px;
  height: 40px;
  border-radius: 13px;
  background: linear-gradient(135deg, #5b4bff, #a855f7 52%, #ff4d8d);
  color: #fff;
  display: grid;
  place-items: center;
  font-size: 0.82rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  box-shadow: 0 10px 20px -10px rgba(91, 75, 255, 0.9);
  flex: none;
}

.brand-text span {
  background: linear-gradient(120deg, #5b4bff, #c026d3);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
}

.nav-links a {
  padding: 9px 15px;
  border-radius: 999px;
  font-size: 0.92rem;
  font-weight: 600;
  color: #4a4568;
  transition: background 0.18s ease, color 0.18s ease, transform 0.18s ease;
}

.nav-links a:hover {
  background: #f1eeff;
  color: var(--indigo);
}

.nav-links a.active {
  color: #fff;
  background: linear-gradient(135deg, #5b4bff, #8b5cf6);
  box-shadow: 0 10px 20px -12px rgba(91, 75, 255, 0.95);
}

.nav-toggle {
  display: none;
  width: 44px;
  height: 44px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #fff;
  cursor: pointer;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
}

.nav-toggle span {
  display: block;
  width: 20px;
  height: 2px;
  border-radius: 2px;
  background: var(--ink);
  transition: transform 0.2s ease, opacity 0.2s ease;
}

.nav-toggle[aria-expanded="true"] span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}

.nav-toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}

.nav-toggle[aria-expanded="true"] span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

.hero {
  position: relative;
  padding: 64px 0 54px;
  overflow: hidden;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1.06fr 0.94fr;
  gap: 56px;
  align-items: center;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 13px;
  border-radius: 999px;
  background: #eeebff;
  border: 1px solid #ded8ff;
  color: var(--indigo);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.eyebrow.light {
  color: #fff;
  background: rgba(255, 255, 255, 0.16);
  border-color: rgba(255, 255, 255, 0.3);
}

.live-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 0 4px rgba(18, 184, 134, 0.16);
  animation: pulse 2.2s ease-in-out infinite;
  flex: none;
}

@keyframes pulse {
  0%,
  100% {
    box-shadow: 0 0 0 4px rgba(18, 184, 134, 0.16);
  }
  50% {
    box-shadow: 0 0 0 7px rgba(18, 184, 134, 0.06);
  }
}

.hero h1 {
  margin: 22px 0 20px;
  font-size: clamp(2.7rem, 5.4vw, 4.5rem);
  font-weight: 800;
  letter-spacing: -0.045em;
}

.grad-text {
  background: linear-gradient(120deg, #5b4bff, #c026d3 55%, #ff4d8d);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.lead {
  max-width: 540px;
  color: var(--muted);
  font-size: 1.08rem;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 30px;
}

.hero-points {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 22px;
  margin-top: 26px;
  color: var(--muted);
  font-size: 0.88rem;
}

.hero-points li {
  display: inline-flex;
  align-items: center;
  gap: 7px;
}

.hero-points .icon {
  color: var(--green);
  font-size: 1rem;
}

.hero-visual {
  position: relative;
  display: grid;
  place-items: center;
  min-height: 450px;
}

.hero-blob {
  position: absolute;
  border-radius: 50%;
  filter: blur(8px);
  opacity: 0.6;
}

.blob-a {
  width: 270px;
  height: 270px;
  top: -20px;
  right: 10px;
  background: radial-gradient(circle, #c9c0ff, #f0b7ff);
}

.blob-b {
  width: 230px;
  height: 230px;
  bottom: -10px;
  left: 0;
  background: radial-gradient(circle, #ffc9dd, #ffe4b8);
}

.hero-panel {
  position: relative;
  z-index: 2;
  width: min(100%, 402px);
  padding: 22px;
  border-radius: 28px;
  background: rgba(255, 255, 255, 0.76);
  border: 1px solid rgba(255, 255, 255, 0.95);
  box-shadow: 0 42px 80px -42px rgba(64, 42, 150, 0.5);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  animation: float 7s ease-in-out infinite;
}

@keyframes float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-10px);
  }
}

.panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 16px;
}

.panel-kicker {
  display: block;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted-soft);
}

.panel-head strong {
  display: block;
  font-size: 1.08rem;
}

.panel-badge {
  padding: 6px 11px;
  border-radius: 999px;
  background: #eefbf7;
  border: 1px solid #c9f0e5;
  color: #0b8f73;
  font-size: 0.72rem;
  font-weight: 700;
  white-space: nowrap;
}

.sched-card {
  display: grid;
  gap: 2px;
  margin-bottom: 10px;
  padding: 14px 16px;
  border-radius: 16px;
  background: #f9f8ff;
  border: 1px solid #ece9fb;
  border-left: 4px solid var(--ca);
}

.sched-time {
  font-size: 0.67rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ca);
}

.sched-card strong {
  font-size: 0.96rem;
}

.sched-meta {
  font-size: 0.76rem;
  color: var(--muted);
}

.panel-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 16px;
  color: var(--muted);
  font-size: 0.8rem;
  font-weight: 600;
}

.panel-dots {
  display: flex;
  gap: 4px;
}

.panel-dots i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #d8d3ee;
}

.panel-dots i:first-child {
  background: var(--indigo);
}

.float-badge {
  position: absolute;
  z-index: 3;
  right: -6px;
  bottom: 30px;
  display: flex;
  align-items: center;
  gap: 10px;
  max-width: 190px;
  padding: 12px 16px;
  border-radius: 18px;
  background: #fff;
  box-shadow: 0 22px 44px -24px rgba(40, 20, 100, 0.5);
  color: var(--muted);
  font-size: 0.75rem;
  font-weight: 600;
  line-height: 1.35;
}

.float-star {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: 13px;
  background: linear-gradient(135deg, #ffb020, #ff4d8d);
  color: #fff;
  font-size: 0.84rem;
  font-weight: 800;
  flex: none;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 20px;
  border: 0;
  border-radius: 14px;
  font-size: 0.92rem;
  font-weight: 700;
  line-height: 1.2;
  text-align: center;
  white-space: nowrap;
  cursor: pointer;
  transition: transform 0.18s ease, box-shadow 0.18s ease, background 0.18s ease, border-color 0.18s ease, filter 0.18s ease;
}

.btn .icon {
  font-size: 1.05em;
}

.btn-primary {
  color: #fff;
  background: linear-gradient(135deg, #5b4bff, #8b5cf6 60%, #c026d3);
  box-shadow: 0 14px 30px -16px rgba(91, 75, 255, 0.95);
}

.btn-primary:hover {
  transform: translateY(-2px);
  filter: saturate(1.08);
  box-shadow: 0 20px 36px -16px rgba(91, 75, 255, 1);
}

.btn-ghost {
  color: var(--ink);
  background: #fff;
  border: 1px solid var(--line);
  box-shadow: 0 8px 18px -16px rgba(30, 20, 80, 0.5);
}

.btn-ghost:hover {
  background: #f7f5ff;
  border-color: #cec7f2;
  transform: translateY(-1px);
}

.btn-soft {
  color: var(--indigo);
  background: #f1eeff;
}

.btn-light {
  color: #4526c9;
  background: #fff;
  box-shadow: 0 18px 36px -20px rgba(0, 0, 0, 0.45);
}

.btn-light:hover {
  transform: translateY(-2px);
}

.btn-sm {
  padding: 9px 14px;
  border-radius: 11px;
  font-size: 0.82rem;
}

.btn.is-disabled,
.btn:disabled {
  opacity: 0.62;
  cursor: not-allowed;
  box-shadow: none;
  transform: none;
  pointer-events: none;
}

.stats-band {
  padding: 28px 0;
  color: #fff;
  background: linear-gradient(120deg, #241a63, #4a2fbd 55%, #7c3aed);
  box-shadow: 0 30px 60px -46px rgba(36, 26, 99, 0.9);
}

.stats-band .stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  text-align: center;
}

.stats-band strong {
  display: block;
  font-size: 1.95rem;
  font-weight: 800;
  letter-spacing: -0.03em;
}

.stats-band span {
  color: rgba(255, 255, 255, 0.72);
  font-size: 0.83rem;
}

.section {
  padding: 74px 0;
}

.section-tint {
  background: linear-gradient(180deg, #f2efff, #faf9ff);
  border-block: 1px solid #ece8ff;
}

.section-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 24px;
  margin-bottom: 34px;
}

.section-head h2 {
  margin-top: 14px;
  font-size: clamp(1.7rem, 3vw, 2.35rem);
}

.section-head p {
  max-width: 560px;
  margin-top: 10px;
  color: var(--muted);
}

.section-head.center {
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.section-head.center p {
  margin-inline: auto;
}

.text-link {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding-bottom: 4px;
  border-bottom: 2px solid #d8d2ff;
  color: var(--indigo);
  font-size: 0.9rem;
  font-weight: 700;
  transition: gap 0.18s ease;
}

.text-link:hover {
  gap: 11px;
}

.course-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(270px, 1fr));
  gap: 24px;
}

.course-card {
  position: relative;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: #fff;
  box-shadow: 0 24px 50px -46px rgba(40, 20, 100, 0.6);
  transition: transform 0.22s ease, box-shadow 0.22s ease, border-color 0.22s ease;
}

.course-card:hover {
  transform: translateY(-5px);
  border-color: #d9d2fb;
  box-shadow: 0 32px 60px -40px rgba(49, 29, 120, 0.55);
}

.course-top {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 18px;
  overflow: hidden;
  color: #fff;
  background: linear-gradient(135deg, var(--ca), var(--cb));
}

.course-top::after {
  content: "";
  position: absolute;
  width: 130px;
  height: 130px;
  top: -70px;
  right: -30px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.14);
  pointer-events: none;
}

.course-code {
  position: relative;
  z-index: 1;
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.course-rating {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 9px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.2);
  font-size: 0.77rem;
  font-weight: 700;
  backdrop-filter: blur(4px);
}

.course-rating .icon {
  font-size: 0.9rem;
}

.course-body {
  display: flex;
  flex: 1;
  flex-direction: column;
  padding: 18px 18px 14px;
}

.dept-tag {
  align-self: flex-start;
  padding: 4px 9px;
  border-radius: 999px;
  background: #f5f3ff;
  border: 1px solid #ebe7ff;
  color: var(--ca);
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.course-body h3 {
  margin: 12px 0 8px;
  font-size: 1.14rem;
  font-weight: 800;
}

.course-desc {
  display: -webkit-box;
  overflow: hidden;
  min-height: 2.7em;
  color: var(--muted);
  font-size: 0.87rem;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.course-meta {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px 10px;
  margin-top: 14px;
  color: var(--muted);
  font-size: 0.77rem;
}

.course-meta li {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.course-meta .icon {
  color: var(--ca);
  font-size: 0.95rem;
}

.course-meta span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.seat-meter {
  height: 6px;
  margin-top: 16px;
  overflow: hidden;
  border-radius: 99px;
  background: #efedfa;
}

.seat-meter span {
  display: block;
  height: 100%;
  min-width: 6%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--ca), var(--cb));
}

.seat-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 6px;
  color: var(--muted);
  font-size: 0.71rem;
  font-weight: 600;
}

.seat-label span {
  color: var(--muted-soft);
}

.course-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: auto;
  padding: 14px 18px;
  border-top: 1px solid var(--line);
  background: #fdfcff;
}

.course-term {
  color: var(--muted);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.dept-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 16px;
}

.dept-tile {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 6px;
  overflow: hidden;
  padding: 22px 20px 18px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: #fff;
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}

.dept-tile::before {
  content: "";
  position: absolute;
  inset: 0 0 auto;
  height: 5px;
  background: linear-gradient(90deg, var(--ca), var(--cb));
}

.dept-tile:hover {
  transform: translateY(-4px);
  border-color: #d9d2fb;
  box-shadow: 0 24px 44px -38px rgba(40, 20, 100, 0.5);
}

.dept-tile h3 {
  font-size: 1rem;
}

.dept-tile .dept-count {
  color: var(--muted);
  font-size: 0.75rem;
  font-weight: 600;
}

.dept-tile .icon {
  position: absolute;
  right: 16px;
  bottom: 16px;
  color: var(--ca);
  font-size: 1rem;
  transition: transform 0.2s ease;
}

.dept-tile:hover .icon {
  transform: translateX(3px);
}

.steps {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;
}

.step {
  padding: 26px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: #fff;
  box-shadow: var(--shadow);
}

.step-num {
  display: inline-block;
  padding: 5px 10px;
  border-radius: 999px;
  background: #eeebff;
  color: var(--indigo);
  font-size: 0.76rem;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.step h3 {
  margin: 16px 0 8px;
  font-size: 1.14rem;
}

.step p {
  color: var(--muted);
  font-size: 0.89rem;
}

.cta-band {
  padding: 0 0 84px;
}

.cta-inner {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
  overflow: hidden;
  padding: 48px;
  border-radius: 30px;
  color: #fff;
  background: linear-gradient(120deg, #4f2bd6, #7c3aed 45%, #e0448b);
  box-shadow: 0 32px 64px -32px rgba(91, 75, 255, 0.7);
}

.cta-inner::after {
  content: "";
  position: absolute;
  width: 320px;
  height: 320px;
  right: -80px;
  bottom: -180px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.28), transparent 65%);
  pointer-events: none;
}

.cta-inner h2 {
  margin: 12px 0 8px;
  font-size: clamp(1.7rem, 3vw, 2.4rem);
}

.cta-inner p {
  max-width: 480px;
  color: rgba(255, 255, 255, 0.8);
}

.cta-inner .btn {
  position: relative;
  z-index: 1;
}

.page-hero {
  position: relative;
  overflow: hidden;
  padding: 58px 0 100px;
  color: #fff;
}

.page-hero::after {
  content: "";
  position: absolute;
  width: 440px;
  height: 440px;
  top: -200px;
  right: -90px;
  border-radius: 50%;
