import { JSDOM, VirtualConsole } from 'jsdom';
import path from 'path';

const pages = ['index.html','catalog.html','register.html','profile.html'];
const errors = [];

async function load(file) {
  const vc = new VirtualConsole();
  vc.on('jsdomError', e => errors.push(`${file}: jsdomError: ${e.message}`));
  vc.on('error', (...a) => errors.push(`${file}: console.error: ${a.join(' ')}`));
  const dom = await JSDOM.fromFile(path.join('/work', file), {
    runScripts: 'dangerously',
    resources: 'usable',
    pretendToBeVisual: true,
    url: 'file://' + path.join('/work', file),
    virtualConsole: vc
  });
  await new Promise(res => {
    if (dom.window.document.readyState === 'complete') res();
    else dom.window.addEventListener('load', res, { once: true });
  });
  await new Promise(r => setTimeout(r, 50));
  return dom;
}

function fire(el, type) {
  el.dispatchEvent(new el.ownerDocument.defaultView.Event(type, { bubbles: true }));
}

const results = [];

const home = await load('index.html');
const w = home.window, d = w.document;
results.push(['home featured cards', d.querySelectorAll('[data-featured] .course-card').length, 4]);
results.push(['home dept tiles', d.querySelectorAll('[data-dept-tiles] .dept-tile').length, 10]);
results.push(['home active nav', d.querySelectorAll('.nav-links a.active').length, 1]);
home.window.close();

const cat = await load('catalog.html');
{
  const w = cat.window, d = w.document;
  results.push(['catalog cards', d.querySelectorAll('[data-course-grid] .course-card').length, 18]);
  const search = d.querySelector('[data-search]');
  search.value = 'machine';
  fire(search, 'input');
  results.push(['search machine', d.querySelectorAll('[data-course-grid] .course-card').length, 1]);
  const reset = d.querySelector('[data-clear-filters]');
  reset.click();
  results.push(['reset search', d.querySelectorAll('[data-course-grid] .course-card').length, 18]);
  const dept = d.querySelector('[data-filter-dept]');
  dept.value = 'Design';
  fire(dept, 'change');
  results.push(['filter Design', d.querySelectorAll('[data-course-grid] .course-card').length, 2]);
  const avail = d.querySelector('[data-filter-availability]');
  avail.value = 'full';
  fire(avail, 'change');
  results.push(['filter full in Design', d.querySelectorAll('[data-course-grid] .course-card').length, 1]);
  const emptyReset = d.querySelector('[data-empty] [data-clear-filters]');
