import { chromium } from 'playwright';
const browser = await chromium.launch();
const errors = [];
const rows = [];

async function auditContext(viewport, label) {
  const ctx = await browser.newContext({ viewport, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  page.on('console', m => { if (m.type() === 'error') errors.push(`${label} console: ${m.text()}`); });
  page.on('pageerror', e => errors.push(`${label} pageerror: ${e.message}`));
  page.on('requestfailed', r => errors.push(`${label} requestfailed: ${r.url()} ${r.failure()?.errorText}`));

  for (const file of ['index.html', 'catalog.html', 'register.html', 'profile.html']) {
    await page.goto(`http://localhost:8123/${file}`, { waitUntil: 'networkidle' });
    const info = await page.evaluate(() => ({
      scroll: document.documentElement.scrollWidth,
      client: document.documentElement.clientWidth,
      navLinks: document.querySelectorAll('.nav-links a').length,
      page: document.body.dataset.page
    }));
    rows.push([`${label} ${file} overflow`, info.scroll <= info.client + 1, `${info.scroll}<=${info.client}`]);
    rows.push([`${label} ${file} nav links`, info.navLinks === 4, String(info.navLinks)]);
  }

  if (viewport.width < 820) {
    await page.goto('http://localhost:8123/index.html', { waitUntil: 'networkidle' });
    await page.click('[data-nav-toggle]');
    const open = await page.locator('.nav-links').evaluate(el => el.classList.contains('open'));
    rows.push([`${label} mobile nav opens`, open, String(open)]);
    await page.click('.nav-links a[href="catalog.html"]');
    await page.waitForLoadState('networkidle');
    rows.push([`${label} mobile nav navigates`, page.url().endsWith('/catalog.html'), page.url()]);
  }
  await ctx.close();
}

